export function recipeServings(recipe) {
 const explicit=Number(recipe.servings);
 if(Number.isFinite(explicit)&&explicit>0)return explicit;
 const stated=(recipe.directions||[]).join(" ").match(/\b(?:recipe serves|serves)\s+(\d+)\b/i);
 if(stated&&Number(stated[1])>0)return Number(stated[1]);
 return yields[recipe.title?.trim()]||recommendations.find(item=>item.title===recipe.title)?.servings||0;
}
